// Filtra, normaliza y deja traza. Un solo lugar donde mirar cuando
// alguien pregunte "¿por qué no me llegó el recordatorio?".
const filas = $input.all().filter((item) => item.json.telefono);

console.log(`[Recordatorio 21:00] Negocios sin movimientos hoy: ${filas.length}`);

if (filas.length === 0) {
  return [];
}

return filas.map((item) => {
  // Meta exige el número en formato internacional y solo dígitos.
  const telefono = String(item.json.telefono).replace(/\D/g, '');
  const contacto = String(item.json.contacto || '').split(' ')[0] || 'por aquí';

  console.log(`[Recordatorio 21:00] → ${item.json.negocio} (***${telefono.slice(-4)})`);

  return {
    json: {
      negocioId: item.json.negocio_id,
      negocio: String(item.json.negocio),
      telefono,
      contacto,
    },
  };
});

// No se corta el workflow por un envío fallido: se registra y se sigue con
// los demás negocios.
for (const item of $input.all()) {
  const detalle = JSON.stringify(item.json).slice(0, 800);
  console.error('[Recordatorio 21:00] ERROR de envío:', detalle);
}
return $input.all();
